import json
import os
import subprocess
from dataclasses import dataclass
from typing import Optional
SCRIPT_PATH = '/opt/travel/jobs/fare_monitor.py'

@dataclass
class FareJobResult:
    ok: bool
    exit_code: int
    drops_found: int
    error: Optional[str] = None

def _parse_output(stdout: str) -> int:
    try:
        payload = json.loads(stdout.strip().splitlines()[-1])
        return int(payload.get('drops', 0))
    except (ValueError, IndexError, AttributeError):
        return 0

def run_fare_alert_job(origin: str, destination: str, depart_date: str, timeout_seconds: int=120) -> FareJobResult:
    if len(origin) != 3 or len(destination) != 3:
        return FareJobResult(ok=False, exit_code=-1, drops_found=0, error='IATA codes must be 3 letters')
    command = ['python3', SCRIPT_PATH, '--origin', origin.upper(), '--destination', destination.upper(), '--date', depart_date]
    # Make sure the job script is executable by the worker's group (owner rwx, group r-x, others none)
    try:
        os.chmod(SCRIPT_PATH, 0o750)
    except OSError as exc:
        return FareJobResult(ok=False, exit_code=-1, drops_found=0, error=str(exc))
    try:
        completed = subprocess.run(command, capture_output=True, text=True, timeout=timeout_seconds)
    except subprocess.TimeoutExpired:
        return FareJobResult(ok=False, exit_code=-1, drops_found=0, error='job timed out')
    except OSError as exc:
        return FareJobResult(ok=False, exit_code=-1, drops_found=0, error=str(exc))
    if completed.returncode != 0:
        return FareJobResult(ok=False, exit_code=completed.returncode, drops_found=0, error=completed.stderr.strip()[:500])
    return FareJobResult(ok=True, exit_code=0, drops_found=_parse_output(completed.stdout))
